import CryptoKit
import Foundation

/// Pure decisions about what to capture and how to classify it.
public enum CaptureRules {
    /// Markers from nspasteboard.org: apps set these on content that must not enter history.
    public static let skipMarkers: Set<String> = [
        "org.nspasteboard.ConcealedType",
        "org.nspasteboard.TransientType",
        "org.nspasteboard.AutoGeneratedType",
        "de.petermaurer.TransientPasteboardType",
    ]

    public static let defaultIgnoredApps: Set<String> = [
        "com.apple.keychainaccess",
        "com.apple.Passwords",
        "com.1password.1password",
        "com.agilebits.onepassword7",
        "com.bitwarden.desktop",
    ]

    /// Largest clip kept, summed over all representations, and largest single representation.
    public static let maxClipBytes = 20 * 1024 * 1024
    public static let maxRepresentationBytes = 10 * 1024 * 1024

    static let imageTypes: Set<String> = ["public.png", "public.tiff", "public.jpeg", "public.heic"]
    /// Image data that comes with a file reference is the image itself (a screenshot's floating thumbnail,
    /// a browser image copy). TIFF is left out: Finder puts the file's icon there.
    static let embeddedImageTypes: Set<String> = ["public.png", "public.jpeg", "public.heic"]
    static let fileURLType = "public.file-url"

    public static func shouldSkip(types: Set<String>) -> Bool {
        !types.isDisjoint(with: skipMarkers)
    }

    /// Dynamic (`dyn.`) types are per-process aliases and cannot be restored meaningfully.
    public static func isStorable(type: String) -> Bool {
        !type.hasPrefix("dyn.") && !skipMarkers.contains(type)
    }

    /// Which of a pasteboard item's types to read. Drops duplicates that are expensive to materialize:
    /// TIFF beside PNG (AppKit converts it uncompressed on read) and legacy aliases of modern types.
    public static func typesToRead(_ types: [String]) -> [String] {
        let storable = types.filter(isStorable)
        let modern = storable.filter { !isLegacyAlias($0) }
        var result = modern.isEmpty ? storable : modern
        if result.contains("public.png") { result.removeAll { $0 == "public.tiff" } }
        return result
    }

    static func isLegacyAlias(_ type: String) -> Bool {
        type.hasPrefix("NeXT ") || type.hasPrefix("Apple ") || type.hasPrefix("CorePasteboardFlavorType")
            || (type.hasPrefix("NS") && type.hasSuffix("PboardType"))
    }

    /// Drops representations that are too large on their own or would push the clip over its cap,
    /// keeping the rest so one huge type never costs the whole clip.
    public static func withinBudget(_ reps: [Representation]) -> [Representation] {
        var total = 0
        return reps.filter { rep in
            guard rep.data.count <= maxRepresentationBytes, total + rep.data.count <= maxClipBytes else { return false }
            total += rep.data.count
            return true
        }
    }

    public static func kind(types: Set<String>, string: String?) -> ClipKind {
        if types.contains(fileURLType) {
            return types.isDisjoint(with: embeddedImageTypes) ? .file : .image
        }
        if let string, !string.isEmpty {
            return isLink(string) ? .link : .text
        }
        if !types.isDisjoint(with: imageTypes) { return .image }
        return .text
    }

    static func isLink(_ string: String) -> Bool {
        let trimmed = string.trimmingCharacters(in: .whitespacesAndNewlines)
        guard !trimmed.contains(where: \.isWhitespace),
            let url = URL(string: trimmed), let scheme = url.scheme?.lowercased()
        else { return false }
        return ["http", "https"].contains(scheme) && url.host() != nil
    }

    /// Identity of a clip's content, independent of representation order.
    public static func contentHash(_ representations: [Representation]) -> String {
        var hasher = SHA256()
        for rep in representations.sorted(by: { ($0.item, $0.type) < ($1.item, $1.type) }) {
            hasher.update(data: Data("\(rep.item)\u{0}\(rep.type)\u{0}\(rep.data.count)\u{0}".utf8))
            hasher.update(data: rep.data)
        }
        return hasher.finalize().map { String(format: "%02x", $0) }.joined()
    }
}
